namespace sv_8670be57920d4e7097bf39f4a0a09a4b.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@namespace sv_8670be57920d4e7097bf39f4a0a09a4b.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var status = GetStepStatus(stepIndex);
            <li class="step-item @status" @onclick="() => HandleStepClick(stepIndex)">
                <span class="step-circle">
                    @if (status == "completed")
                    {
                        <span class="checkmark">&#10003;</span>
                    }
                    else
                    {
                        @(stepIndex + 1)
                    }
                </span>
                <span class="step-label">@StepNames[stepIndex]</span>
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private string GetStepStatus(int index)
    {
        if (index == CurrentStep) return "active";
        if (index < CurrentStep) return "completed";
        return "future";
    }

    private async Task HandleStepClick(int index)
    {
        if (index < CurrentStep)
        {
            await OnStepClicked.InvokeAsync(index);
        }
    }
}

@namespace sv_8670be57920d4e7097bf39f4a0a09a4b.Components.Pages.Apply

<div class="step-content">
    <h2>Personal Information</h2>

    <div class="form-group">
        <label for="fullName">Full Name *</label>
        <input id="fullName" type="text" @bind="FullName" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-group">
        <label for="email">Email *</label>
        <input id="email" type="email" @bind="Email" @bind:event="oninput" class="form-control" />
        @if (!string.IsNullOrEmpty(_emailError))
        {
            <span class="field-error">@_emailError</span>
        }
    </div>

    <div class="form-group">
        <label for="phone">Phone *</label>
        <input id="phone" type="tel" @bind="Phone" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-group">
        <label for="address">Address *</label>
        <input id="address" type="text" @bind="Address" @bind:event="oninput" class="form-control" />
    </div>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="validation-summary">@_validationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-primary" @onclick="HandleNext" disabled="@_isValidating">
            @if (_isValidating)
            {
                <span>Validating...</span>
            }
            else
            {
                <span>Next</span>
            }
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<PersonalInfoResult> OnNext { get; set; }
    [Parameter, EditorRequired] public IApplicationService ApplicationService { get; set; } = default!;

    private string? _validationError;
    private string? _emailError;
    private bool _isValidating;

    private async Task HandleNext()
    {
        _validationError = null;
        _emailError = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
            string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            _validationError = "All fields are required.";
            return;
        }

        _isValidating = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(Email);
            if (!emailValid)
            {
                _emailError = "Please enter a valid email address.";
                return;
            }

            await OnNext.InvokeAsync(new PersonalInfoResult(FullName, Email, Phone, Address));
        }
        finally
        {
            _isValidating = false;
        }
    }

    public record PersonalInfoResult(string FullName, string Email, string Phone, string Address);
}

@namespace sv_8670be57920d4e7097bf39f4a0a09a4b.Components.Pages.Apply

<div class="work-entry-card">
    <div class="work-entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button class="btn btn-danger-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company" @onchange="e => Update(e, nameof(WorkEntryModel.Company))" class="form-control" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title" @onchange="e => Update(e, nameof(WorkEntryModel.Title))" class="form-control" />
    </div>

    <div class="form-row">
        <div class="form-group half">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate?.ToString("yyyy-MM-dd")" @onchange="e => UpdateDate(e, true)" class="form-control" />
        </div>
        <div class="form-group half">
            <label>End Date</label>
            <input type="date" value="@Entry.EndDate?.ToString("yyyy-MM-dd")" @onchange="e => UpdateDate(e, false)" class="form-control" disabled="@Entry.IsCurrent" />
        </div>
    </div>

    <div class="form-group checkbox-group">
        <label>
            <input type="checkbox" checked="@Entry.IsCurrent" @onchange="e => UpdateCurrent(e)" />
            Currently working here
        </label>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea value="@Entry.Description" @onchange="e => Update(e, nameof(WorkEntryModel.Description))" class="form-control" rows="3"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnChanged { get; set; }

    private void Update(ChangeEventArgs e, string field)
    {
        var value = e.Value?.ToString() ?? "";
        var updated = field switch
        {
            nameof(WorkEntryModel.Company) => Entry with { Company = value },
            nameof(WorkEntryModel.Title) => Entry with { Title = value },
            nameof(WorkEntryModel.Description) => Entry with { Description = value },
            _ => Entry
        };
        OnChanged.InvokeAsync(updated);
    }

    private void UpdateDate(ChangeEventArgs e, bool isStart)
    {
        DateTime.TryParse(e.Value?.ToString(), out var date);
        var updated = isStart
            ? Entry with { StartDate = date == default ? null : date }
            : Entry with { EndDate = date == default ? null : date };
        OnChanged.InvokeAsync(updated);
    }

    private void UpdateCurrent(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        var updated = Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate };
        OnChanged.InvokeAsync(updated);
    }

    public record WorkEntryModel
    {
        public string Company { get; init; } = "";
        public string Title { get; init; } = "";
        public DateTime? StartDate { get; init; }
        public DateTime? EndDate { get; init; }
        public bool IsCurrent { get; init; }
        public string Description { get; init; } = "";
    }
}

@namespace sv_8670be57920d4e7097bf39f4a0a09a4b.Components.Pages.Apply

<div class="step-content">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="@Entries[index]"
                       Index="index"
                       CanRemove="@(Entries.Count > 1)"
                       OnRemove="() => RemoveEntry(index)"
                       OnChanged="entry => UpdateEntry(index, entry)" />
    }

    <button class="btn btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="validation-summary">@_validationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntryForm.WorkEntryModel> Entries { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<List<WorkEntryForm.WorkEntryModel>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? _validationError;

    private void AddEntry()
    {
        Entries.Add(new WorkEntryForm.WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private void UpdateEntry(int index, WorkEntryForm.WorkEntryModel entry)
    {
        Entries[index] = entry;
    }

    private async Task HandleNext()
    {
        _validationError = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) || entry.StartDate == null)
            {
                _validationError = "Each position requires at least a company name, job title, and start date.";
                return;
            }
        }

        await OnNext.InvokeAsync(Entries);
    }
}

