@namespace sv_8670be57920d4e7097bf39f4a0a09a4b.Components.Pages.Apply

<div class="work-entry-card">
    <div class="work-entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button class="btn btn-danger-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company" @onchange="e => Update(e, nameof(WorkEntryModel.Company))" class="form-control" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title" @onchange="e => Update(e, nameof(WorkEntryModel.Title))" class="form-control" />
    </div>

    <div class="form-row">
        <div class="form-group half">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate?.ToString("yyyy-MM-dd")" @onchange="e => UpdateDate(e, true)" class="form-control" />
        </div>
        <div class="form-group half">
            <label>End Date</label>
            <input type="date" value="@Entry.EndDate?.ToString("yyyy-MM-dd")" @onchange="e => UpdateDate(e, false)" class="form-control" disabled="@Entry.IsCurrent" />
        </div>
    </div>

    <div class="form-group checkbox-group">
        <label>
            <input type="checkbox" checked="@Entry.IsCurrent" @onchange="e => UpdateCurrent(e)" />
            Currently working here
        </label>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea value="@Entry.Description" @onchange="e => Update(e, nameof(WorkEntryModel.Description))" class="form-control" rows="3"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnChanged { get; set; }

    private void Update(ChangeEventArgs e, string field)
    {
        var value = e.Value?.ToString() ?? "";
        var updated = field switch
        {
            nameof(WorkEntryModel.Company) => Entry with { Company = value },
            nameof(WorkEntryModel.Title) => Entry with { Title = value },
            nameof(WorkEntryModel.Description) => Entry with { Description = value },
            _ => Entry
        };
        OnChanged.InvokeAsync(updated);
    }

    private void UpdateDate(ChangeEventArgs e, bool isStart)
    {
        DateTime.TryParse(e.Value?.ToString(), out var date);
        var updated = isStart
            ? Entry with { StartDate = date == default ? null : date }
            : Entry with { EndDate = date == default ? null : date };
        OnChanged.InvokeAsync(updated);
    }

    private void UpdateCurrent(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
